from test_bufftap import test
food="stock(250071,1248401); stock(250067,1248400); consumables('food'); local B=BuffTap; B:SetConsumableChoice(B:ConsumableFamily('food'),250071); "
test('F05 chosen Strength food sees another food effect without replacing it',food+"aura('player',1248421,'Well Fed',900,900); local s,t=B:FoodPreferenceStatus(); assert(s=='different' and t:find(\"won't replace\",1,true),s); refresh(); assert(not (B.action and B.action.familyKey=='food'))")
test('F05 chosen food effect is compatible without claiming the exact meal',food+"aura('player',1248422,'Well Fed',900,900); local s,t=B:FoodPreferenceStatus(); assert(s=='compatible' and t:find('exact meal',1,true),s)")
test('F05 unrecognised Well Fed is ambiguous',food+"aura('player',999999,'Well Fed',900,900); local s=B:FoodPreferenceStatus(); assert(s=='ambiguous',s)")
test('F05 no food buff is missing, Auto never claims stats',food+"assert(B:FoodPreferenceStatus()=='missing'); B:SetConsumableChoice(B:ConsumableFamily('food'),nil); assert(B:FoodPreferenceStatus()=='auto')")
test('F05 unreadable auras are unknown, combat waits',food+"C_UnitAuras.GetAuraDataByIndex=function() error('restricted') end; B:InvalidateAura('player'); assert(B:FoodPreferenceStatus()=='unknown'); combat=true; assert(B:FoodPreferenceStatus()=='unknown')")
test('F05 turned off reads as disabled',"BuffTap.db.consumablesEnabled=false; assert(BuffTap:FoodPreferenceStatus()=='disabled')")
test('F10 explanations: missing stock, ready, resting',"local B=BuffTap; consumables('flask'); B.db.consumableFamilies.flask=true; local f=B:ConsumableFamily('flask'); B:SetConsumableChoice(f,13510); local t=B:ConsumableExplanation(f); assert(t:find('not in your bags',1,true),t); stock(13510,17626); B:InvalidateConsumables(); t=B:ConsumableExplanation(f); assert(t:find('Ready',1,true),t); B.db.consumablesPauseResting=true; IsResting=function() return true end; t=B:ConsumableExplanation(f); assert(t:find('resting',1,true),t)")
test('F10 explanation is skipped for checklist parents',"local B=BuffTap; assert(B:ConsumableExplanation({multi=true,key='elixir'})=='')")
test('F10 tracking status sentences',"local B=BuffTap; B.db.helperTracking=false; assert(B:TrackingStatusText():find('turned off',1,true)); B.db.helperTracking=true; B.db.helperTracker=0; assert(B:TrackingStatusText():find('Choose',1,true)); B.trackingFollowPending=true; assert(B:TrackingStatusText():find('Following',1,true))")
test('F10 diagnostics mention a paused effect without names',"local B=BuffTap; B.effectPauses={[1]=true}; local joined=table.concat(B:DiagnosticsLines(),'\\n'); assert(joined:find('Retry reminders',1,true))")
chk="local B=BuffTap; stock(13452,17538); stock(250350,1250985); consumables('ferocity'); B.db.consumableFamilies['elixir:13452']=true; B.db.consumableFamilies['elixir:250350']=true; local P=B:ConsumableFamily('ferocity'); "
test('1.24.7 checklist: ticked elixirs missing with stock are reported missing',chk+"local t=B:ConsumableChecklistExplanation(P); assert(t:find('Selected: 2',1,true) and t:find('Missing: 2',1,true),t)")
test('1.24.7 checklist: an active effect is active, the other still missing',chk+"aura('player',17538,'Elixir of the Mongoose',1700,1800); B:InvalidateConsumables(); local t=B:ConsumableChecklistExplanation(P); assert(t:find('Active: 1',1,true) and t:find('Missing: 1',1,true),t)")
test('1.24.7 checklist: an expiring effect is expiring',chk+"aura('player',17538,'Elixir of the Mongoose',60,1800); B:InvalidateConsumables(); local t=B:ConsumableChecklistExplanation(P); assert(t:find('Expiring: 1',1,true),t)")
test('1.24.7 checklist: out of stock is not mistaken for missing',"local B=BuffTap; consumables('ferocity'); B.db.consumableFamilies['elixir:13452']=true; local P=B:ConsumableFamily('ferocity'); local t=B:ConsumableChecklistExplanation(P); assert(t:find('Out of stock: 1',1,true) and t:find('Missing: 0',1,true),t)")
test('1.24.7 checklist: a failed effect reads as paused',chk+"B.effectPauses={[13452]=true}; local t=B:ConsumableChecklistExplanation(P); assert(t:find('Paused: 1',1,true) and t:find('Retry reminders',1,true),t)")
test('1.24.7 checklist: nothing ticked, combat, unreadable auras and off',"local B=BuffTap; consumables('ferocity'); local P=B:ConsumableFamily('ferocity'); for _,c in ipairs(P.children) do B.db.consumableFamilies[c.key]=false end; assert(B:ConsumableChecklistExplanation(P):find('No effects selected',1,true)); B.db.consumableFamilies['elixir:13452']=true; stock(13452,17538); combat=true; assert(B:ConsumableChecklistExplanation(P):find('after combat',1,true)); combat=false; C_UnitAuras.GetAuraDataByIndex=function() error('restricted') end; B:InvalidateAura('player'); local t=B:ConsumableChecklistExplanation(P); assert(type(t)=='string' and t~='',t); B.db.consumablesEnabled=false; assert(B:ConsumableChecklistExplanation(P):find('turned off',1,true))")
test('1.24.7 checklist: opening the explanation changes nothing',chk+"refresh(); local before=BuffTap.button.attrs.type1; local nb=0; for _ in pairs(bindings) do nb=nb+1 end; for i=1,200 do B:ConsumableChecklistExplanation(P) end; local na=0; for _ in pairs(bindings) do na=na+1 end; assert(BuffTap.button.attrs.type1==before and nb==na)")
test('1.24.7 checklist: non-checklist family returns empty',"assert(BuffTap:ConsumableChecklistExplanation({key='food'})=='')")
test('1.24.7 checklist: hover tooltip shows status for the current setup only',chk+"B:Options(); local row; for _,r in ipairs(B.options.consumableRows) do if r.family.key=='ferocity' then row=r end end; assert(row and row.scripts.OnEnter); row.scripts.OnEnter(row)")
